MODELS = {
  "cheap": "Short lookup, formatting or extraction",
  "mid": "Normal edit, explanation or small refactor",
  "frontier": "Multi-step reasoning, architecture, hard bugs"}

def route(message):
    qs = {"model": {"type": "choice", "criteria": MODELS,
          "instructions": "Which model tier does this request need?"}}
    ans = decide(message, qs)["model"]
    # the cutoff lives here, not in the prompt
    return "frontier" if ans["probabilities"].get("frontier", 0) > 0.45 else ans["choice"]
